import { create } from 'zustand'
import type { ScanResult } from './nimbus/scan'
import type { VaultEntry } from './vault'
import { isDryRun } from './dry-run'

export type DeskId = 'nimbus' | 'mint' | 'nado' | 'arcus' | 'lighter' | 'vault'

interface TerminalState {
  desk: DeskId
  dryRun: boolean
  vault: VaultEntry | null
  armed: boolean
  nimbusScan: ScanResult | null
  nimbusScanning: boolean
  mintArmed: boolean
  mintHits: MintHit[]
  mintScouting: boolean
  lastError?: string
  tapeVersion: number
  setDesk: (d: DeskId) => void
  setDryRun: (v: boolean) => void
  setVault: (v: VaultEntry | null) => void
  setArmed: (v: boolean) => void
  setNimbusScan: (s: ScanResult | null) => void
  setNimbusScanning: (v: boolean) => void
  setMintArmed: (v: boolean) => void
  setMintHits: (h: MintHit[]) => void
  setMintScouting: (v: boolean) => void
  setLastError: (e?: string) => void
  bumpTape: () => void
}

export interface MintHit {
  slug: string
  name: string
  chainId: number
  chain?: string
  contract?: string
  priceNative: number
  preferSeaDrop: boolean
  status: 'watch' | 'ready' | 'armed' | 'skipped'
  reason: string
  url?: string
}

export const useTerminal = create<TerminalState>((set) => ({
  desk: 'nimbus',
  dryRun: isDryRun(),
  vault: null,
  armed: false,
  nimbusScan: null,
  nimbusScanning: false,
  mintArmed: false,
  mintHits: [],
  mintScouting: false,
  tapeVersion: 0,
  setDesk: (desk) => set({ desk }),
  setDryRun: (dryRun) => set({ dryRun }),
  setVault: (vault) => set({ vault }),
  setArmed: (armed) => set({ armed }),
  setNimbusScan: (nimbusScan) => set({ nimbusScan }),
  setNimbusScanning: (nimbusScanning) => set({ nimbusScanning }),
  setMintArmed: (mintArmed) => set({ mintArmed }),
  setMintHits: (mintHits) => set({ mintHits }),
  setMintScouting: (mintScouting) => set({ mintScouting }),
  setLastError: (lastError) => set({ lastError }),
  bumpTape: () => set((s) => ({ tapeVersion: s.tapeVersion + 1 })),
}))
