export interface LighterBook {
  symbol: string
  marketId: number
  status: string
  marketType: string
}

const HOSTS = [
  'https://mainnet.zklighter.elliot.ai',
  'https://api.rh.lighter.xyz',
]

export async function fetchLighterBooks(): Promise<LighterBook[]> {
  let lastErr: unknown
  for (const host of HOSTS) {
    try {
      const res = await fetch(`${host}/api/v1/orderBooks`, {
        headers: { Accept: 'application/json' },
      })
      if (!res.ok) continue
      const j = (await res.json()) as { order_books?: any[]; code?: number }
      const books = Array.isArray(j.order_books) ? j.order_books : []
      return books.slice(0, 50).map((b) => ({
        symbol: String(b.symbol || ''),
        marketId: Number(b.market_id ?? 0),
        status: String(b.status || ''),
        marketType: String(b.market_type || ''),
      }))
    } catch (e) {
      lastErr = e
    }
  }
  throw lastErr instanceof Error ? lastErr : new Error('Lighter orderBooks failed')
}
