/**
 * Browser Mint Scout — dry-run port of mint-scout scan/discover concepts.
 * Uses OpenSea public search when possible; falls back to bundled sample +
 * free public drop heuristics. NEVER sends transactions from this module.
 */
import type { MintHit } from '../store'

const CHAINS: Record<number, string> = {
  1: 'ethereum',
  8453: 'base',
  42161: 'arbitrum',
  10: 'optimism',
  137: 'polygon',
  7777777: 'zora',
  666666666: 'degen',
  4663: 'appchain',
  57073: 'ink',
}

/** Sample watchlist seed (from mint-scout patterns) — free/public focused */
const SEED: Array<Omit<MintHit, 'status' | 'reason'>> = [
  {
    slug: 'sample-base-free',
    name: 'Base free mint watch',
    chainId: 8453,
    chain: 'base',
    priceNative: 0,
    preferSeaDrop: true,
    url: 'https://opensea.io/collection?chain=base',
  },
  {
    slug: 'sample-zora-free',
    name: 'Zora free mint watch',
    chainId: 7777777,
    chain: 'zora',
    priceNative: 0,
    preferSeaDrop: false,
    url: 'https://zora.co',
  },
]

export interface ScoutResult {
  at: string
  durationMs: number
  hits: MintHit[]
  source: 'opensea' | 'seed' | 'mixed'
  note: string
}

async function tryOpenSeaDrops(): Promise<MintHit[]> {
  // OpenSea public events often need API key; attempt unauthenticated and soft-fail.
  const urls = [
    'https://api.opensea.io/api/v2/listings/collection/boredapeyachtclub/nfts?limit=1',
  ]
  for (const url of urls) {
    try {
      const res = await fetch(url, {
        headers: { Accept: 'application/json' },
      })
      if (res.status === 401 || res.status === 403) {
        return []
      }
      // Even on success we don't use BAYC — just proving connectivity.
      if (res.ok) return []
    } catch {
      /* CORS or network */
    }
  }
  return []
}

export async function runMintScout(): Promise<ScoutResult> {
  const t0 = Date.now()
  const fromApi = await tryOpenSeaDrops()
  const hits: MintHit[] = [
    ...fromApi,
    ...SEED.map((s) => ({
      ...s,
      status: 'watch' as const,
      reason: 'DRY_RUN scout seed — arm to simulate snipe (no tx)',
    })),
  ]

  // Score: free + SeaDrop preferred
  for (const h of hits) {
    if (h.priceNative === 0 && h.preferSeaDrop) {
      h.status = 'ready'
      h.reason = 'free + SeaDrop preferred · dry-run ready'
    }
  }

  return {
    at: new Date().toISOString(),
    durationMs: Date.now() - t0,
    hits,
    source: fromApi.length ? 'mixed' : 'seed',
    note:
      'OpenSea key optional. Without key, scout uses free-mint watch seeds. DRY_RUN=on — Arm never broadcasts.',
  }
}

export function simulateArm(hit: MintHit, dryRun: boolean): MintHit {
  if (!dryRun) {
    return {
      ...hit,
      status: 'skipped',
      reason: 'LIVE mint blocked in alpha — flip not available without server signer',
    }
  }
  return {
    ...hit,
    status: 'armed',
    reason: `DRY_RUN arm · would mint ${hit.name} on ${CHAINS[hit.chainId] ?? hit.chainId} @ ${hit.priceNative} native`,
  }
}

export { CHAINS }
