/** Global execution gate. Default ON — never posts live orders unless flipped. */
const KEY = 'stark.live.dryRun'

export function isDryRun(): boolean {
  try {
    const v = sessionStorage.getItem(KEY)
    if (v === null) return true
    return v !== '0'
  } catch {
    return true
  }
}

export function setDryRun(on: boolean) {
  sessionStorage.setItem(KEY, on ? '1' : '0')
}

export interface ExecIntent {
  desk: string
  action: string
  detail: string
  at: string
  dryRun: boolean
}

const TAPE_KEY = 'stark.live.tape'

export function pushTape(entry: Omit<ExecIntent, 'at' | 'dryRun'> & { dryRun?: boolean }) {
  const full: ExecIntent = {
    ...entry,
    at: new Date().toISOString(),
    dryRun: entry.dryRun ?? isDryRun(),
  }
  try {
    const prev = JSON.parse(sessionStorage.getItem(TAPE_KEY) || '[]') as ExecIntent[]
    prev.unshift(full)
    sessionStorage.setItem(TAPE_KEY, JSON.stringify(prev.slice(0, 200)))
  } catch {
    /* ignore */
  }
  return full
}

export function getTape(): ExecIntent[] {
  try {
    return JSON.parse(sessionStorage.getItem(TAPE_KEY) || '[]') as ExecIntent[]
  } catch {
    return []
  }
}
