import type { ReactNode } from 'react'
import { useTerminal, type DeskId } from '../../lib/store'
import { setDryRun as persistDryRun } from '../../lib/dry-run'
import { maskAddress } from '../../lib/vault'

const DESKS: Array<{ id: DeskId; label: string; tag: string }> = [
  { id: 'nimbus', label: 'Nimbus', tag: 'weather' },
  { id: 'mint', label: 'Mint Scout', tag: 'nft' },
  { id: 'nado', label: 'Nado', tag: 'perp' },
  { id: 'arcus', label: 'Arcus', tag: 'sr' },
  { id: 'lighter', label: 'Lighter', tag: 'rh' },
  { id: 'vault', label: 'Vault', tag: 'keys' },
]

export function TerminalChrome({ children }: { children: ReactNode }) {
  const desk = useTerminal((s) => s.desk)
  const setDesk = useTerminal((s) => s.setDesk)
  const dryRun = useTerminal((s) => s.dryRun)
  const setDryRun = useTerminal((s) => s.setDryRun)
  const vault = useTerminal((s) => s.vault)
  const armed = useTerminal((s) => s.armed)
  const lastError = useTerminal((s) => s.lastError)

  return (
    <div className="min-h-screen flex flex-col">
      <header className="border-b border-slate-800/80 bg-slate-950/90 px-4 py-3">
        <div className="flex flex-wrap items-center gap-3">
          <div className="flex items-center gap-2">
            <span className="text-lg font-semibold tracking-tight text-cyan-300">
              StaRK
            </span>
            <span className="text-slate-400 text-sm">Live Terminal</span>
            <span className="rounded bg-violet-500/20 px-1.5 py-0.5 text-[10px] uppercase text-violet-300">
              alpha
            </span>
          </div>

          <div
            className={`rounded-full px-2.5 py-1 text-xs font-semibold ${
              dryRun
                ? 'bg-amber-500/15 text-amber-300'
                : 'bg-rose-500/20 text-rose-300'
            }`}
          >
            {dryRun ? 'DRY_RUN' : 'LIVE GATE OPEN'}
          </div>

          {armed && (
            <div className="rounded-full bg-emerald-500/20 px-2.5 py-1 text-xs font-semibold text-emerald-300">
              ARMED
            </div>
          )}

          <div className="ml-auto flex flex-wrap items-center gap-2 text-xs text-slate-400">
            {vault ? (
              <span className="mono text-slate-300">
                {maskAddress(vault.address)}
              </span>
            ) : (
              <span>no burner key</span>
            )}
            <button
              type="button"
              className="rounded-md border border-slate-700 px-2 py-1 hover:bg-slate-800"
              onClick={() => {
                const next = !dryRun
                persistDryRun(next)
                setDryRun(next)
              }}
            >
              Toggle DRY_RUN
            </button>
          </div>
        </div>

        <nav className="mt-3 flex flex-wrap gap-1">
          {DESKS.map((d) => (
            <button
              key={d.id}
              type="button"
              onClick={() => setDesk(d.id)}
              className={`rounded-md px-3 py-1.5 text-sm ${
                desk === d.id
                  ? 'bg-cyan-600/30 text-cyan-200 ring-1 ring-cyan-500/40'
                  : 'text-slate-400 hover:bg-slate-800/80 hover:text-slate-200'
              }`}
            >
              {d.label}
              <span className="ml-1 text-[10px] uppercase text-slate-500">
                {d.tag}
              </span>
            </button>
          ))}
        </nav>

        {lastError && (
          <div className="mt-2 truncate text-xs text-rose-400" title={lastError}>
            {lastError}
          </div>
        )}
      </header>

      <main className="flex-1">{children}</main>

      <footer className="border-t border-slate-800/80 px-4 py-2 text-[11px] text-slate-500">
        Session-only vault · burner keys only · DRY_RUN default · NFA · not financial advice ·
        unlisted alpha path
      </footer>
    </div>
  )
}
