import { useTerminal } from '../../lib/store'
import { runMintScout, simulateArm, CHAINS } from '../../lib/mint/scout'
import { pushTape } from '../../lib/dry-run'

export function MintDesk() {
  const hits = useTerminal((s) => s.mintHits)
  const scouting = useTerminal((s) => s.mintScouting)
  const setHits = useTerminal((s) => s.setMintHits)
  const setScouting = useTerminal((s) => s.setMintScouting)
  const mintArmed = useTerminal((s) => s.mintArmed)
  const setMintArmed = useTerminal((s) => s.setMintArmed)
  const dryRun = useTerminal((s) => s.dryRun)
  const vault = useTerminal((s) => s.vault)
  const setLastError = useTerminal((s) => s.setLastError)
  const bumpTape = useTerminal((s) => s.bumpTape)

  async function onScout() {
    setScouting(true)
    setLastError(undefined)
    try {
      const res = await runMintScout()
      setHits(res.hits)
      pushTape({
        desk: 'mint',
        action: 'scout',
        detail: `${res.hits.length} hits · ${res.source} · ${res.durationMs}ms`,
      })
      bumpTape()
    } catch (e) {
      setLastError(e instanceof Error ? e.message : String(e))
    } finally {
      setScouting(false)
    }
  }

  function onArmHit(slug: string) {
    if (!mintArmed) {
      setLastError('Toggle Mint Arm first')
      return
    }
    setHits(
      hits.map((h) => {
        if (h.slug !== slug) return h
        const next = simulateArm(h, dryRun)
        pushTape({
          desk: 'mint',
          action: 'arm_hit',
          detail: next.reason,
        })
        return next
      }),
    )
    bumpTape()
  }

  return (
    <div className="space-y-4 p-4">
      <div className="flex flex-wrap items-center gap-3">
        <h2 className="text-base font-semibold text-emerald-300">Mint Scout</h2>
        <span className="text-[10px] uppercase text-slate-500">
          port of mint-scout · dry-run sniper
        </span>
        <button
          type="button"
          onClick={onScout}
          disabled={scouting}
          className="rounded-md bg-emerald-700 px-3 py-1.5 text-sm font-medium disabled:opacity-50"
        >
          {scouting ? 'Scouting…' : 'Scout'}
        </button>
        <button
          type="button"
          onClick={() => setMintArmed(!mintArmed)}
          className={`rounded-md px-3 py-1.5 text-sm ${
            mintArmed ? 'bg-rose-700' : 'bg-slate-700'
          }`}
        >
          {mintArmed ? 'Disarm scout' : 'Arm scout'}
        </button>
        <span className="text-xs text-slate-400">
          {vault ? `burner ${vault.address.slice(0, 8)}…` : 'no burner'} · DRY_RUN=
          {dryRun ? 'on' : 'off'}
        </span>
      </div>

      <p className="text-xs text-slate-400 max-w-2xl">
        Real mint-scout Node bot lives in <code className="mono">/workspace/mint-scout</code>.
        This desk ports scout+arm UX for the browser: free-mint watch seeds, SeaDrop preference,
        arm only logs dry-run intents (no broadcast).
      </p>

      <div className="overflow-x-auto rounded-lg border border-slate-800">
        <table className="min-w-full text-left text-sm">
          <thead className="bg-slate-900 text-xs uppercase text-slate-400">
            <tr>
              <th className="px-3 py-2">Name</th>
              <th className="px-3 py-2">Chain</th>
              <th className="px-3 py-2">Price</th>
              <th className="px-3 py-2">Status</th>
              <th className="px-3 py-2">Reason</th>
              <th className="px-3 py-2"></th>
            </tr>
          </thead>
          <tbody>
            {hits.map((h) => (
              <tr key={h.slug} className="border-t border-slate-800/80">
                <td className="px-3 py-2 font-medium">{h.name}</td>
                <td className="px-3 py-2 mono text-xs">
                  {CHAINS[h.chainId] ?? h.chainId}
                </td>
                <td className="px-3 py-2 tabular-nums">{h.priceNative}</td>
                <td className="px-3 py-2 text-xs uppercase text-amber-300">{h.status}</td>
                <td className="px-3 py-2 text-xs text-slate-400">{h.reason}</td>
                <td className="px-3 py-2">
                  <button
                    type="button"
                    onClick={() => onArmHit(h.slug)}
                    className="rounded bg-violet-700/80 px-2 py-1 text-xs"
                  >
                    Arm dry-run
                  </button>
                </td>
              </tr>
            ))}
            {!hits.length && (
              <tr>
                <td colSpan={6} className="px-3 py-8 text-center text-slate-500">
                  Run Scout to load free-mint watchlist (dry-run).
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  )
}
