import { useState } from 'react'
import { useTerminal } from '../../lib/store'
import {
  clearVault,
  loadVault,
  maskKey,
  saveVault,
  type SignatureType,
} from '../../lib/vault'
import { getTape, pushTape } from '../../lib/dry-run'

export function VaultPanel() {
  const vault = useTerminal((s) => s.vault)
  const setVault = useTerminal((s) => s.setVault)
  const dryRun = useTerminal((s) => s.dryRun)
  const setLastError = useTerminal((s) => s.setLastError)
  const bumpTape = useTerminal((s) => s.bumpTape)
  const tapeVersion = useTerminal((s) => s.tapeVersion)

  const [pk, setPk] = useState('')
  const [funder, setFunder] = useState('')
  const [sigType, setSigType] = useState<SignatureType>(1)
  const [ack, setAck] = useState(false)

  function onSave() {
    if (!ack) {
      setLastError('Acknowledge burner-only warning before saving a key.')
      return
    }
    try {
      const entry = saveVault({
        privateKey: pk || loadVault()?.privateKey || '',
        funderAddress: funder,
        signatureType: sigType,
      })
      setVault(entry)
      setPk('')
      setLastError(undefined)
      pushTape({
        desk: 'vault',
        action: 'save_key',
        detail: `session vault ${entry.address}`,
      })
      bumpTape()
    } catch (e) {
      setLastError(e instanceof Error ? e.message : String(e))
    }
  }

  function onClear() {
    clearVault()
    setVault(null)
    setPk('')
    pushTape({ desk: 'vault', action: 'clear_key', detail: 'session vault cleared' })
    bumpTape()
  }

  const tape = getTape()
  void tapeVersion

  return (
    <div className="mx-auto max-w-xl space-y-4 p-4">
      <div className="rounded-lg border border-amber-700/50 bg-amber-950/30 p-3 text-sm text-amber-100">
        <strong>Burner keys only.</strong> Private keys stay in{' '}
        <code className="mono">sessionStorage</code> for this tab — never
        localStorage, never uploaded, never committed. Closing the tab wipes the
        vault. Do not paste a funded main wallet. Prefer a fresh burner with
        dust-only balances.
      </div>

      <label className="flex items-start gap-2 text-sm text-slate-300">
        <input
          type="checkbox"
          checked={ack}
          onChange={(e) => setAck(e.target.checked)}
          className="mt-1"
        />
        <span>
          I understand this is session-only, burner-only, and DRY_RUN is{' '}
          {dryRun ? 'ON' : 'OFF'}.
        </span>
      </label>

      <label className="block text-sm">
        <span className="text-slate-400">Private key</span>
        <input
          type="password"
          className="mt-1 w-full rounded border border-slate-700 bg-slate-900 px-3 py-2 mono text-sm"
          placeholder={
            vault ? `saved ${maskKey(vault.privateKey)}` : '0x… burner only'
          }
          value={pk}
          onChange={(e) => setPk(e.target.value)}
          autoComplete="off"
        />
      </label>

      <label className="block text-sm">
        <span className="text-slate-400">Funder / proxy (optional)</span>
        <input
          className="mt-1 w-full rounded border border-slate-700 bg-slate-900 px-3 py-2 mono text-sm"
          value={funder}
          onChange={(e) => setFunder(e.target.value)}
          placeholder="0x…"
        />
      </label>

      <label className="block text-sm">
        <span className="text-slate-400">Signature type (Polymarket)</span>
        <select
          className="mt-1 w-full rounded border border-slate-700 bg-slate-900 px-3 py-2 text-sm"
          value={sigType}
          onChange={(e) => setSigType(Number(e.target.value) as SignatureType)}
        >
          <option value={0}>0 — EOA</option>
          <option value={1}>1 — Email / Magic proxy</option>
          <option value={2}>2 — Gnosis Safe</option>
        </select>
      </label>

      <div className="flex gap-2">
        <button
          type="button"
          onClick={onSave}
          disabled={!ack || (!pk && !vault)}
          className="rounded-md bg-sky-600 px-3 py-1.5 text-sm font-medium disabled:opacity-40"
        >
          Save to session vault
        </button>
        <button
          type="button"
          onClick={onClear}
          className="rounded-md bg-slate-700 px-3 py-1.5 text-sm"
        >
          Clear
        </button>
      </div>

      {vault && (
        <div className="text-xs text-slate-400">
          Connected <code className="mono text-slate-200">{vault.address}</code> ·
          saved {new Date(vault.savedAt).toLocaleString()}
        </div>
      )}

      <div className="rounded-lg border border-slate-800 p-3">
        <h3 className="mb-2 text-sm font-medium text-slate-200">Execution tape</h3>
        <ul className="max-h-48 space-y-1 overflow-y-auto text-[11px] text-slate-400 mono">
          {tape.slice(0, 30).map((t, i) => (
            <li key={`${t.at}-${i}`}>
              [{t.dryRun ? 'DRY' : 'LIVE'}] {t.desk}/{t.action} — {t.detail}
            </li>
          ))}
          {!tape.length && <li>No intents yet</li>}
        </ul>
      </div>
    </div>
  )
}
