import { useEffect } from 'react'
import { TerminalChrome } from './components/shell/TerminalChrome'
import { NimbusDesk } from './components/nimbus/NimbusDesk'
import { MintDesk } from './components/mint/MintDesk'
import { VaultPanel } from './components/vault/VaultPanel'
import { ArcusDesk, LighterDesk, NadoDesk } from './components/venues/VenueDesks'
import { useTerminal } from './lib/store'
import { loadVault } from './lib/vault'

export default function App() {
  const desk = useTerminal((s) => s.desk)
  const setVault = useTerminal((s) => s.setVault)

  useEffect(() => {
    setVault(loadVault())
  }, [setVault])

  return (
    <TerminalChrome>
      {desk === 'nimbus' && <NimbusDesk />}
      {desk === 'mint' && <MintDesk />}
      {desk === 'nado' && <NadoDesk />}
      {desk === 'arcus' && <ArcusDesk />}
      {desk === 'lighter' && <LighterDesk />}
      {desk === 'vault' && <VaultPanel />}
    </TerminalChrome>
  )
}
