/**
 * Session-only key vault. Keys never leave the browser tab (sessionStorage).
 * Burner-only warnings. Cleared when the tab closes.
 */
import { Wallet } from 'ethers'

export type SignatureType = 0 | 1 | 2

export interface VaultEntry {
  privateKey: string
  address: string
  funderAddress?: string
  signatureType: SignatureType
  label?: string
  savedAt: string
  desk?: string
}

const KEY = 'stark.live.vault.v1'

export function loadVault(): VaultEntry | null {
  try {
    const raw = sessionStorage.getItem(KEY)
    if (!raw) return null
    const v = JSON.parse(raw) as VaultEntry
    if (!v?.privateKey) return null
    return v
  } catch {
    return null
  }
}

export function saveVault(input: {
  privateKey: string
  funderAddress?: string
  signatureType?: SignatureType
  label?: string
  desk?: string
}): VaultEntry {
  const pk = input.privateKey.trim()
  const wallet = new Wallet(pk.startsWith('0x') ? pk : `0x${pk}`)
  const entry: VaultEntry = {
    privateKey: wallet.privateKey,
    address: wallet.address,
    funderAddress: input.funderAddress?.trim() || undefined,
    signatureType: (input.signatureType ?? 1) as SignatureType,
    label: input.label,
    desk: input.desk,
    savedAt: new Date().toISOString(),
  }
  sessionStorage.setItem(KEY, JSON.stringify(entry))
  return entry
}

export function clearVault() {
  sessionStorage.removeItem(KEY)
}

export function maskKey(pk: string): string {
  if (!pk) return ''
  const s = pk.startsWith('0x') ? pk : `0x${pk}`
  return `${s.slice(0, 6)}…${s.slice(-4)}`
}

export function maskAddress(addr: string): string {
  if (!addr || addr.length < 10) return addr || ''
  return `${addr.slice(0, 6)}…${addr.slice(-4)}`
}
