export interface NadoTicker {
  symbol: string
  productId: number
  bid: number
  ask: number
  mid: number
  change24h?: number
  volume24h?: number
}

const WANTED = [
  'BTC-PERP_USDT0',
  'ETH-PERP_USDT0',
  'SOL-PERP_USDT0',
  'HYPE-PERP_USDT0',
  'SPY-PERP_USDT0',
  'QQQ-PERP_USDT0',
]

/**
 * CORS-safe Nado archive ticker endpoint used by the official data plane.
 * It exposes last prices/24h stats. Bid/ask remain 0 here; signed execution
 * hooks route to the gateway/MCP outside the static browser app.
 */
export async function fetchNadoPrices(): Promise<NadoTicker[]> {
  const res = await fetch('https://archive.prod.nado.xyz/v2/tickers', {
    headers: { Accept: 'application/json' },
  })
  if (!res.ok) throw new Error(`Nado tickers ${res.status}`)
  const j = (await res.json()) as Record<string, any>
  return WANTED.flatMap((symbol) => {
    const t = j[symbol]
    if (!t) return []
    const last = Number(t.last_price ?? t.lastPrice ?? 0)
    return [
      {
        symbol: symbol.replace('_USDT0', ''),
        productId: Number(t.product_id ?? t.productId ?? 0),
        bid: 0,
        ask: 0,
        mid: last,
        change24h: Number(t.price_change_percent_24h ?? t.priceChangePercent24h ?? 0),
        volume24h: Number(t.quote_volume ?? t.quoteVolume ?? 0),
      },
    ]
  })
}
