export interface ArcusMarket {
  marketId: number
  name: string
  status: string
  tickSize: string
  markPrice?: number
  indexPrice?: number
}

export async function fetchArcusMarkets(): Promise<ArcusMarket[]> {
  const res = await fetch('https://api.arcus.xyz/v1/markets', {
    headers: { Accept: 'application/json' },
  })
  if (!res.ok) throw new Error(`Arcus markets ${res.status}`)
  const j = (await res.json()) as { markets?: any[] }
  const markets = Array.isArray(j.markets) ? j.markets : []
  return markets.slice(0, 40).map((m) => ({
    marketId: Number(m.marketId ?? m.id ?? 0),
    name: String(m.marketDisplayName || m.fullAssetName || m.baseAsset || '?'),
    status: String(m.status || ''),
    tickSize: String(m.tickSize || ''),
    markPrice: m.markPrice != null ? Number(m.markPrice) : undefined,
    indexPrice: m.indexPrice != null ? Number(m.indexPrice) : undefined,
  }))
}

/** Best-effort ticker endpoint (path may vary by Arcus version). */
export async function fetchArcusTicker(marketId: number): Promise<{ bid?: number; ask?: number } | null> {
  try {
    const res = await fetch(`https://api.arcus.xyz/v1/orderbook?marketId=${marketId}&depth=1`, {
      headers: { Accept: 'application/json' },
    })
    if (!res.ok) return null
    const j = await res.json()
    const bids = j?.bids || j?.data?.bids || []
    const asks = j?.asks || j?.data?.asks || []
    return {
      bid: bids[0] ? Number(bids[0][0] ?? bids[0].price) : undefined,
      ask: asks[0] ? Number(asks[0][0] ?? asks[0].price) : undefined,
    }
  } catch {
    return null
  }
}
