import { useCallback, useEffect, useState } from 'react'
import { fetchNadoPrices, type NadoTicker } from '../../lib/venues/nado'
import { fetchArcusMarkets, type ArcusMarket } from '../../lib/venues/arcus'
import { fetchLighterBooks, type LighterBook } from '../../lib/venues/lighter'
import { pushTape } from '../../lib/dry-run'
import { useTerminal } from '../../lib/store'

function fmt(n: number | undefined, d = 2) {
  if (n == null || !Number.isFinite(n) || n === 0) return '—'
  if (n >= 1000) return n.toLocaleString(undefined, { maximumFractionDigits: 2 })
  if (n >= 1) return n.toFixed(d)
  return n.toPrecision(4)
}

export function NadoDesk() {
  const [rows, setRows] = useState<NadoTicker[]>([])
  const [err, setErr] = useState<string>()
  const [at, setAt] = useState<string>()
  const dryRun = useTerminal((s) => s.dryRun)
  const bumpTape = useTerminal((s) => s.bumpTape)

  const refresh = useCallback(async () => {
    try {
      const data = await fetchNadoPrices()
      setRows(data)
      setAt(new Date().toISOString())
      setErr(data.length ? undefined : 'No prices (CORS/network). Local proxy may help.')
    } catch (e) {
      setErr(e instanceof Error ? e.message : String(e))
    }
  }, [])

  useEffect(() => {
    void refresh()
    const id = setInterval(() => void refresh(), 15_000)
    return () => clearInterval(id)
  }, [refresh])

  return (
    <div className="space-y-4 p-4">
      <div className="flex flex-wrap items-center gap-3">
        <h2 className="text-base font-semibold text-cyan-300">Nado · live book</h2>
        <button type="button" onClick={() => void refresh()} className="rounded-md bg-slate-700 px-3 py-1.5 text-sm">
          Refresh
        </button>
        <button
          type="button"
          className="rounded-md bg-violet-700 px-3 py-1.5 text-sm"
          onClick={() => {
            pushTape({
              desk: 'nado',
              action: 'exec_hook',
              detail: dryRun
                ? 'DRY_RUN place_order hook — wire to Nado MCP / gateway signer offline'
                : 'LIVE place blocked in alpha SPA',
            })
            bumpTape()
          }}
        >
          Dry-run exec hook
        </button>
        <span className="text-xs text-slate-400">{at ? `as of ${at}` : ''}</span>
      </div>
      {err && <p className="text-xs text-amber-400">{err}</p>}
      <table className="min-w-full text-left text-sm rounded-lg border border-slate-800 overflow-hidden">
        <thead className="bg-slate-900 text-xs uppercase text-slate-400">
          <tr>
            <th className="px-3 py-2">Market</th>
            <th className="px-3 py-2">Last</th>
            <th className="px-3 py-2">24h</th>
            <th className="px-3 py-2">Quote volume</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((r) => (
            <tr key={r.productId} className="border-t border-slate-800/80">
              <td className="px-3 py-2 font-medium">{r.symbol}</td>
              <td className="px-3 py-2 tabular-nums text-cyan-300">{fmt(r.mid)}</td>
              <td className={`px-3 py-2 tabular-nums ${(r.change24h ?? 0) >= 0 ? 'text-emerald-300' : 'text-rose-300'}`}>{fmt(r.change24h)}%</td>
              <td className="px-3 py-2 tabular-nums">${fmt(r.volume24h, 0)}</td>
            </tr>
          ))}
          {!rows.length && (
            <tr>
              <td colSpan={4} className="px-3 py-6 text-center text-slate-500">
                Waiting for gateway.prod.nado.xyz…
              </td>
            </tr>
          )}
        </tbody>
      </table>
      <p className="text-[11px] text-slate-500">
        Live 24h tickers via Nado archive API. Order placement stays DRY_RUN — use user-nado MCP /
        farm scripts for signed posts.
      </p>
    </div>
  )
}

