import { useEffect, useState } from 'react'
import { useTerminal } from '../../lib/store'
import { getCachedScan, runScan, type CityScanRow } from '../../lib/nimbus/scan'
import { STRATEGY } from '../../lib/nimbus/engine'
import { pushTape } from '../../lib/dry-run'

export function NimbusDesk() {
  const scan = useTerminal((s) => s.nimbusScan)
  const scanning = useTerminal((s) => s.nimbusScanning)
  const setScan = useTerminal((s) => s.setNimbusScan)
  const setScanning = useTerminal((s) => s.setNimbusScanning)
  const setLastError = useTerminal((s) => s.setLastError)
  const dryRun = useTerminal((s) => s.dryRun)
  const armed = useTerminal((s) => s.armed)
  const setArmed = useTerminal((s) => s.setArmed)
  const vault = useTerminal((s) => s.vault)
  const bumpTape = useTerminal((s) => s.bumpTape)
  const [selected, setSelected] = useState<string | null>(null)

  useEffect(() => {
    const cached = getCachedScan()
    if (cached) setScan(cached)
  }, [setScan])

  async function onScan() {
    setScanning(true)
    setLastError(undefined)
    try {
      const res = await runScan({ force: true, maxCities: 10 })
      setScan(res)
      if (res.error) setLastError(res.error)
      pushTape({
        desk: 'nimbus',
        action: 'scan',
        detail: `${res.cities.length} cities · ${res.durationMs}ms`,
      })
      bumpTape()
      if (res.cities[0]) setSelected(res.cities[0].cityKey)
    } catch (e) {
      setLastError(e instanceof Error ? e.message : String(e))
    } finally {
      setScanning(false)
    }
  }

  function onDryTick() {
    const intents = scan?.plan?.intents ?? []
    pushTape({
      desk: 'nimbus',
      action: 'dry_tick',
      detail: dryRun
        ? `would place ${intents.length} intents (cap $${STRATEGY.hardCapUsd}) · armed=${armed}`
        : `LIVE tick blocked in alpha SPA — use nimbus server for CLOB`,
    })
    bumpTape()
  }

  const cities = scan?.cities ?? []
  const city: CityScanRow | undefined = cities.find((c) => c.cityKey === selected) || cities[0]

  return (
    <div className="space-y-4 p-4">
      <div className="flex flex-wrap items-center gap-3">
        <h2 className="text-base font-semibold text-sky-300">Nimbus · Polymarket weather</h2>
        <span className="text-[10px] uppercase text-slate-500">
          real Gamma + Open-Meteo/METAR engine port
        </span>
        <button
          type="button"
          onClick={onScan}
          disabled={scanning}
          className="rounded-md bg-sky-600 px-3 py-1.5 text-sm font-medium text-white disabled:opacity-50"
        >
          {scanning ? 'Scanning…' : 'Scan now'}
        </button>
        <button
          type="button"
          onClick={() => setArmed(!armed)}
          className={`rounded-md px-3 py-1.5 text-sm font-medium ${
            armed ? 'bg-rose-700' : 'bg-emerald-700'
          }`}
        >
          {armed ? 'Disarm' : 'Arm'}
        </button>
        <button
          type="button"
          onClick={onDryTick}
          disabled={!armed}
          className="rounded-md bg-violet-700 px-3 py-1.5 text-sm disabled:opacity-40"
        >
          Dry-run tick
        </button>
        <span className="text-xs text-slate-400">
          {scan
            ? `last ${scan.at} · ${scan.durationMs}ms · ${cities.length} cities`
            : 'no scan yet'}
          {vault ? ` · vault ${vault.address.slice(0, 8)}…` : ' · no key'}
        </span>
      </div>

      <div className="overflow-x-auto rounded-lg border border-slate-800">
        <table className="min-w-full text-left text-sm">
          <thead className="bg-slate-900 text-xs uppercase text-slate-400">
            <tr>
              <th className="px-3 py-2">City</th>
              <th className="px-3 py-2">Obs</th>
              <th className="px-3 py-2">Ens</th>
              <th className="px-3 py-2">Heat</th>
              <th className="px-3 py-2">Best edge</th>
              <th className="px-3 py-2">Signal</th>
            </tr>
          </thead>
          <tbody>
            {cities.map((c) => {
              const top = c.buckets.find((b) => b.side && b.kellyStake > 0)
              return (
                <tr
                  key={c.cityKey}
                  className={`border-t border-slate-800/80 cursor-pointer hover:bg-slate-900/60 ${
                    city?.cityKey === c.cityKey ? 'bg-slate-900/80' : ''
                  }`}
                  onClick={() => setSelected(c.cityKey)}
                >
                  <td className="px-3 py-2">
                    <div className="font-medium">{c.city}</div>
                    <div className="text-[11px] text-slate-500">
                      {c.resolutionStationId ?? c.icao} · {c.eventDate}
                    </div>
                  </td>
                  <td className="px-3 py-2 tabular-nums">
                    {c.observedMax?.toFixed(1) ?? '—'}°{c.unit}
                  </td>
                  <td className="px-3 py-2 tabular-nums">
                    {c.ensembleMax?.toFixed(1) ?? '—'}
                  </td>
                  <td className="px-3 py-2 tabular-nums">
                    {c.remainingHeat?.toFixed(1) ?? '—'}
                    {c.locked && (
                      <span className="ml-1 text-[10px] text-emerald-400">LOCK</span>
                    )}
                  </td>
                  <td className="px-3 py-2 tabular-nums text-sky-300">
                    {(c.bestEdge * 100).toFixed(1)}¢
                  </td>
                  <td className="px-3 py-2 text-xs text-slate-300">
                    {c.ladder ? (
                      <span className="text-violet-300">{c.ladder.reason}</span>
                    ) : top ? (
                      <span>
                        {top.side} {top.label}
                      </span>
                    ) : (
                      <span className="text-slate-500">—</span>
                    )}
                  </td>
                </tr>
              )
            })}
            {!cities.length && (
              <tr>
                <td colSpan={6} className="px-3 py-8 text-center text-slate-500">
                  Hit Scan to pull live Gamma highest-temperature markets and score with the
                  real Nimbus engine.
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      {city && (
        <div className="rounded-lg border border-slate-800 p-3">
          <h3 className="mb-2 text-sm font-medium">Buckets — {city.city}</h3>
          <div className="overflow-x-auto">
            <table className="min-w-full text-left text-xs">
              <thead className="text-slate-500">
                <tr>
                  <th className="px-2 py-1">Bucket</th>
                  <th className="px-2 py-1">YES</th>
                  <th className="px-2 py-1">Model</th>
                  <th className="px-2 py-1">Edge</th>
                  <th className="px-2 py-1">Side</th>
                  <th className="px-2 py-1">Reason</th>
                </tr>
              </thead>
              <tbody>
                {city.buckets.map((b) => (
                  <tr key={b.label} className="border-t border-slate-800/50">
                    <td className="px-2 py-1">{b.label}</td>
                    <td className="px-2 py-1 tabular-nums">
                      {(b.yesPrice * 100).toFixed(0)}¢
                    </td>
                    <td className="px-2 py-1 tabular-nums">
                      {(b.modelP * 100).toFixed(0)}%
                    </td>
                    <td className="px-2 py-1 tabular-nums">
                      {(Math.max(b.edgeYes, b.edgeNo) * 100).toFixed(1)}¢
                    </td>
                    <td className="px-2 py-1">
                      {b.veto ? (
                        <span className="text-rose-400">VETO</span>
                      ) : b.lockYes ? (
                        <span className="text-emerald-400">LOCK YES</span>
                      ) : (
                        b.side || '—'
                      )}
                    </td>
                    <td className="px-2 py-1 text-slate-400">{b.reason}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  )
}
